'use strict';
let mapTool='terrain',terrainBrush=0,stamp={x:4,y:6},mapSelection={x:0,y:0},mapFeedback='选择上方地形名称，再点击地图。';
const terrainNames={0:'可通行地面',7:'障碍（不可通过）',15:'边界（不可通过）'};
const terrainLabel=value=>terrainNames[value]||'原有特殊地形';
function putImage(canvas,img){canvas.width=img.width;canvas.height=img.height;const ctx=canvas.getContext('2d');ctx.putImageData(new ImageData(img.pixels,img.width,img.height),0,0);}
function battleCell(canvas,event,m){const b=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(m.width-1,Math.floor((event.clientX-b.left)*m.width/b.width))),y:Math.max(0,Math.min(m.height-1,Math.floor((event.clientY-b.top)*m.height/b.height)))};}
function drawBattleCanvas(canvas,s,options={}){const img=model.renderMap(s),m=model.mapData(s);putImage(canvas,img);const c=canvas.getContext('2d'),changes=model.exportFeatures().maps[s]?.terrain||{};
 if(options.terrain)for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){const i=y*m.width+x,t=m.terrain[i*2]&15;if([7,15].includes(t)){c.fillStyle=t===7?'#e05e3878':'#43465dab';c.fillRect(x*32,y*16,32,16);c.strokeStyle='#ffe4da';c.beginPath();c.moveTo(x*32+12,y*16+4);c.lineTo(x*32+20,y*16+12);c.moveTo(x*32+20,y*16+4);c.lineTo(x*32+12,y*16+12);c.stroke();}if(Object.hasOwn(changes,i)){c.fillStyle=t===0?'#30d18870':'#ffb53b50';c.fillRect(x*32,y*16,32,16);c.strokeStyle='#e8ff79';c.lineWidth=1;c.strokeRect(x*32+1,y*16+1,30,14);}}
 c.strokeStyle='#f1f3db40';c.lineWidth=.5;for(let x=0;x<=m.width;x++){c.beginPath();c.moveTo(x*32,0);c.lineTo(x*32,img.height);c.stroke();}for(let y=0;y<=m.height;y++){c.beginPath();c.moveTo(0,y*16);c.lineTo(img.width,y*16);c.stroke();}
 for(const a of options.actors||[])if(a.id){c.fillStyle=a.side?'#a74636dd':'#275a3bdd';c.fillRect(a.x*32+6,a.y*16+1,20,14);c.fillStyle='#fff';c.font='bold 10px sans-serif';c.textAlign='center';c.fillText(a.index+1,a.x*32+16,a.y*16+12);if(a.index===options.selected){c.strokeStyle='#ffda64';c.lineWidth=2;c.strokeRect(a.x*32+1,a.y*16+1,30,14);}}
 const exits=model.rules(s,sub).groups.flat().filter(r=>r.type===10);for(const r of exits){c.strokeStyle='#21efcf';c.lineWidth=2;c.strokeRect(r.b*32+1,r.c*16+1,30,14);c.fillStyle='#003f36';c.fillRect(r.b*32+8,r.c*16+2,16,12);c.fillStyle='#b7ffef';c.font='bold 10px sans-serif';c.textAlign='center';c.fillText('撤',r.b*32+16,r.c*16+12);}canvas.dataset.arrivalPoints=exits.length;
 const objects=(options.objects||[]).filter(o=>o.type);for(const o of objects){c.fillStyle='#ffdb79';c.fillRect(o.x*32+1,o.y*16+1,30,14);c.fillStyle='#513509';c.font='bold 10px sans-serif';c.textAlign='center';c.fillText(`物${o.index+1}`,o.x*32+16,o.y*16+12);if(o.index===options.selectedObject){c.strokeStyle='#ffffff';c.lineWidth=2;c.strokeRect(o.x*32,o.y*16,32,16);}}
 canvas.dataset.objectCount=objects.length;canvas.onmousemove=e=>{const cell=battleCell(canvas,e,m),items=objects.filter(o=>o.x===cell.x&&o.y===cell.y);canvas.title=`(${cell.x}, ${cell.y}) · ${terrainLabel(m.terrain[(cell.y*m.width+cell.x)*2]&15)}${items.map(o=>` · 物${o.index+1}：${model.objectName(o)}`).join('')}`;};
 if(options.selection){c.strokeStyle='#ffe34c';c.lineWidth=2;c.strokeRect(options.selection.x*32+1,options.selection.y*16+1,30,14);}
}
function renderMapEditor(){const m=model.mapData(stage);mapSelection.x=Math.min(mapSelection.x,m.width-1);mapSelection.y=Math.min(mapSelection.y,m.height-1);stamp.x=Math.min(stamp.x,m.width-1);stamp.y=Math.min(stamp.y,m.height-1);
 panel.innerHTML=`<div class="sectionhead"><div><h2>关卡地图</h2><p>直接选择地形名称，再点地图修改通行规则。改过的格子会高亮。</p></div><span class="badge">${m.width} × ${m.height} 格</span></div><div class="card"><div class="toolbar assetentry"><button id="openMapAssets">浏览底图素材库</button><span class="hint">全部 46 张战场底图、${model.backgrounds().length} 张剧情背景，以及本图现有地块</span></div><div class="terrainbrushes" aria-label="选择地形笔刷">${Object.entries(terrainNames).map(([v,n])=>`<button class="terrainBrush" data-value="${v}">${n}</button>`).join('')}</div><div class="toolbar"><label>当前操作<select id="mapTool">${eventOptions([['terrain','修改通行规则（点击即修改）'],['inspect','查看 / 选取底图样本'],['stamp','复制底图图案']],mapTool)}</select></label><button id="sampleCell">复制所选格的图案</button><label><input id="copyTerrain" type="checkbox" checked>复制图案时一并复制通行规则</label></div><p id="mapBrushInfo" class="brushinfo"></p><p class="hint">通行规则控制能否走过；草、树、石头等画面图案需用“复制底图图案”替换。</p><div class="toolbar"><label><input id="showTerrain" type="checkbox" checked>显示障碍与修改标记</label><label><input id="showActors" type="checkbox" checked>显示人物</label><label><input id="showObjects" type="checkbox" checked>显示物品</label></div><div class="mapscroll"><canvas id="mapCanvas" aria-label="点击地图修改所选格"></canvas></div><p id="mapInfo"></p><p id="mapFeedback" role="status"></p><div id="mapItems"></div><div class="gridlegend"><span><i style="background:#e66a45"></i>障碍</span><span><i style="background:#51bd8a"></i>已改为可通行</span><span><i style="background:#ffdb79"></i>物品</span></div><details class="nativeLookup"><summary>高级：保留或指定原有特殊地形</summary><p class="hint">其他地形的准确名称和特殊规则尚未确认，保留原编号供进阶编辑；常用通行修改直接使用上面的名称按钮。</p><select id="terrainValue">${Array.from({length:16},(_,v)=>`<option value="${v}">${terrainLabel(v)}（原编号 ${v}）</option>`).join('')}</select><button id="useAdvancedTerrain" class="small">使用此地形笔刷</button></details></div><div class="notice">修改即时保存在当前工程，点“导出新 ROM”后才会进入游戏文件；关闭前也可保存工程。三套出场配置共用地图。尺寸保持原样，特殊忍术与其他地形的移动效果仍需在游戏里检查。</div>`;
 const draw=()=>{drawBattleCanvas($('#mapCanvas'),stage,{terrain:$('#showTerrain').checked,actors:$('#showActors').checked?model.actors(stage,sub):[],objects:$('#showObjects').checked?model.objects(stage,sub):[],selection:mapSelection});const v=model.mapData(stage).terrain[(mapSelection.y*m.width+mapSelection.x)*2]&15;$('#mapInfo').textContent=`所选格 (${mapSelection.x}, ${mapSelection.y}) · ${terrainLabel(v)}`;$('#mapBrushInfo').textContent=mapTool==='terrain'?`正在绘制：${terrainLabel(terrainBrush)}。点击地图即可修改。`:mapTool==='inspect'?'正在查看 / 取样：点击只选中，不会改动地图。选好后点“复制所选格的图案”。':`正在复制图案：来源 (${stamp.x}, ${stamp.y})。点击目标格替换图案。`;$('#mapFeedback').textContent=mapFeedback;panel.querySelectorAll('.terrainBrush').forEach(b=>b.classList.toggle('primary',mapTool==='terrain'&&+b.dataset.value===terrainBrush));const items=model.objects(stage,sub).filter(o=>o.type&&o.x===mapSelection.x&&o.y===mapSelection.y);$('#mapItems').innerHTML=items.map(o=>`<p>物${o.index+1}：${esc(model.objectName(o))} <button class="small editMapObject" data-index="${o.index}">编辑此物品</button></p>`).join('');panel.querySelectorAll('.editMapObject').forEach(b=>b.onclick=()=>{selectedObject=+b.dataset.index;tab='objects';render();});};
 $('#openMapAssets').onclick=()=>openMapAssets('cells');
 $('#mapTool').onchange=e=>{mapTool=e.target.value;draw();};panel.querySelectorAll('.terrainBrush').forEach(b=>b.onclick=()=>{terrainBrush=+b.dataset.value;mapTool='terrain';$('#mapTool').value=mapTool;draw();});
 $('#terrainValue').value=terrainBrush;$('#useAdvancedTerrain').onclick=()=>{terrainBrush=+$('#terrainValue').value;mapTool='terrain';$('#mapTool').value=mapTool;draw();};
 $('#mapCanvas').onclick=e=>run(()=>{const cell=battleCell(e.currentTarget,e,m);mapSelection=cell;if(mapTool==='inspect'){mapFeedback='已选中格子；查看模式不会修改地形。';draw();return;}const before=model.mapData(stage).terrain[(cell.y*m.width+cell.x)*2]&15;if(mapTool==='terrain'&&before===terrainBrush){mapFeedback=`这一格已经是${terrainLabel(before)}。改变画面图案请使用“复制底图图案”。`;draw();return;}model.transaction('编辑地图格',()=>{if(mapTool==='stamp')model.stampCell(stage,cell.x,cell.y,stamp.x,stamp.y,$('#copyTerrain').checked);else model.setTerrain(stage,cell.x,cell.y,terrainBrush);});mapFeedback=mapTool==='stamp'?`已把 (${stamp.x}, ${stamp.y}) 的图案复制到 (${cell.x}, ${cell.y})。`:`已把 (${cell.x}, ${cell.y}) 从${terrainLabel(before)}改为${terrainLabel(terrainBrush)}。`;updateStatus();draw();});
 $('#sampleCell').onclick=()=>{stamp={...mapSelection};mapTool='stamp';$('#mapTool').value='stamp';draw();};for(const id of['showTerrain','showActors','showObjects'])$('#'+id).onchange=draw;draw();
}
function showStoryBackground(container){if(!container||!model)return;container.innerHTML=`<div class="backgroundrow"><div><h3>实际剧情底图（对话区上方）</h3><label>预览底图<select class="backgroundSelect"><option value="default">本关默认</option>${model.backgrounds().map(id=>`<option value="${id}">底图 ${id}</option>`).join('')}</select></label><p class="hint">显示 ROM 中的实际画面。切换这里只用于预览；分支中的底图变化尚未自动跟随。</p></div><canvas class="storyCanvas"></canvas></div>`;const select=container.querySelector('select'),canvas=container.querySelector('canvas');const draw=()=>{try{putImage(canvas,model.renderBackground(stage,select.value==='default'?undefined:+select.value));}catch(e){canvas.width=240;canvas.height=80;const c=canvas.getContext('2d');c.fillStyle='#1c2c22';c.fillRect(0,0,240,80);c.fillStyle='white';c.font='12px sans-serif';c.fillText('本段无可识别默认底图',16,32);c.fillText('请在左侧选择底图预览',16,52);}};select.onchange=draw;draw();}
function renderEvents(){const events=model.events(stage);panel.innerHTML=`<div class="sectionhead"><div><h2>条件剧情</h2><p>在指定方回合开始时检查条件，满足后播放新对白。每条事件单独设置次数。</p></div><button id="addEvent" class="primary" ${events.length>=8?'disabled':''}>新增事件</button></div><div class="notice">“每场一次”限制的是这一条事件；一场战斗可设置多条。每战场最多新增 8 条；原事件较多时导出会进一步检查容量。原有关卡事件会保留。指定人物若未出场，退场条件也会成立；请核对人物和配置。</div><div id="eventList">${events.map((e,i)=>`<div class="card eventcard" data-event="${i}"><div class="sectionhead"><h3>${esc(e.label)}</h3><button class="deleteEvent">删除事件</button></div><div class="eventfields"><label>事件名称<input name="label" value="${esc(e.label)}"></label><label>触发条件<select name="type">${eventOptions([['turn','到指定回合以后'],['absent','指定人物已退场（回合开始检查）']],e.type)}</select></label><label>触发次数<select name="repeat">${eventOptions([['once','每场战斗一次'],['phase','每个指定方回合一次']],e.repeat)}</select></label><label>在哪一方回合检查<select name="phase">${sides(e.phase)}</select></label><label>适用配置<select name="sub">${opts([[3,'全部配置'],[0,'配置 1'],[1,'配置 2'],[2,'配置 3']],e.sub)}</select></label>${e.type==='turn'?`<label>从第几回合开始${number('turn',e.turn,1,99)}</label>`:`<label>人物阵营<select name="side">${sides(e.side)}</select></label><label>指定人物<select name="character">${opts(model.characters.map(c=>[c.id,model.characterName(c.id)]),e.character)}</select></label>`}</div><div class="eventpages">${e.pages.map((p,j)=>`<div class="eventpage" data-page="${j}"><div class="eventSpeaker"><canvas class="portrait" data-portrait="${p.speaker}" width="80" height="80"></canvas><label>第 ${j+1} 段说话人<select name="speaker">${opts(model.characters.map(c=>[c.id,model.characterName(c.id)]),p.speaker)}</select></label></div><label>对白<textarea rows="3" name="text">${esc(p.text)}</textarea></label><div class="toolbar"><button class="eventPaginate">按 24 字 × 2 行分页</button><button class="removePage" ${e.pages.length<=1?'disabled':''}>删除这段</button></div></div>`).join('')}</div><div class="toolbar"><button class="addPage">增加一段对白</button><button class="primary saveEvent">保存此事件</button></div><p class="hint">对白内可使用【分页】，一条事件可以有多名人物轮流发言。</p></div>`).join('')||'<div class="card"><p>本关还没有自定义条件对白。点击“新增事件”开始。</p></div>'}</div>`;
 $('#addEvent').onclick=()=>run(()=>transaction('新增条件剧情',()=>model.setEvents(stage,[...events,{label:`新事件 ${events.length+1}`,type:'turn',repeat:'once',phase:0,sub:3,turn:2,side:1,character:18,pages:[{speaker:7,text:'注意敌人的动向！'}]}])));
 paintPortraits(panel);panel.querySelectorAll('.eventcard').forEach(card=>{const i=+card.dataset.event;const read=()=>{const e={...events[i]};card.querySelectorAll('.eventfields [name]').forEach(f=>e[f.name]=['label','type','repeat'].includes(f.name)?f.value:+f.value);e.pages=[...card.querySelectorAll('.eventpage')].map(p=>({speaker:+p.querySelector('[name=speaker]').value,text:p.querySelector('[name=text]').value}));return e;};
 const save=e=>run(()=>transaction('修改条件剧情',()=>{const list=model.events(stage);list[i]=e;model.setEvents(stage,list);}));
 card.querySelector('[name=type]').onchange=()=>save(read());card.querySelector('.saveEvent').onclick=()=>save(read());card.querySelector('.deleteEvent').onclick=()=>run(()=>transaction('删除条件剧情',()=>model.setEvents(stage,events.filter((_,j)=>i!==j))));
 card.querySelector('.addPage').onclick=()=>{const e=read();e.pages.push({speaker:1,text:'新的对白。'});save(e);};
 card.querySelectorAll('.eventpage').forEach(el=>{const j=+el.dataset.page;el.querySelector('[name=speaker]').onchange=e=>drawPortrait(el.querySelector('.portrait'),+e.target.value);el.querySelector('.removePage').onclick=()=>{const e=read();e.pages.splice(j,1);save(e);};el.querySelector('.eventPaginate').onclick=()=>{const input=el.querySelector('textarea');input.value=paginateEvent(input.value);};});
 });
}
function eventOptions(items,value){return items.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${esc(t)}</option>`).join('');}
function paginateEvent(value){const tokens=model.tokenize(value.replaceAll('【分页】','')),lines=[];let line='',count=0;for(const t of tokens){if(t.raw?.[0]===10){lines.push(line);line='';count=0;continue;}if(t.raw&&t.raw[0]<32)throw Error('含原版控制码时请手动分页');if(count>=24){lines.push(line);line='';count=0;}line+=t.char||(t.raw.length===2?`{字${E.hex(t.raw[0]*256+t.raw[1],4)}}`:String.fromCharCode(t.raw[0]));count++;}if(line)lines.push(line);const pages=[];for(let i=0;i<lines.length;i+=2)pages.push(lines.slice(i,i+2).join('\n'));return pages.join('【分页】');}

let assetKind='cells',assetSelection=null;
function cellSamples(s){const m=model.mapData(s),seen=new Set(),out=[];for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){const key=m.layers.map(data=>data?Array.from(data.slice((y*m.width*2+x*2)*2,(y*m.width*2+x*2+2)*2)).join(','):'').join('|')+':'+(m.terrain[(y*m.width+x)*2]&15);if(seen.has(key))continue;seen.add(key);out.push({x,y,terrain:m.terrain[(y*m.width+x)*2]&15});}return out;}
function openMapAssets(kind='cells'){assetKind=kind;assetSelection=null;let dialog=$('#mapAssets');if(!dialog){dialog=document.createElement('dialog');dialog.id='mapAssets';document.body.append(dialog);}renderMapAssets();dialog.showModal();}
function renderMapAssets(){const dialog=$('#mapAssets'),cells=cellSamples(stage),backgrounds=model.backgrounds();dialog.innerHTML=`<div class="modalhead"><div><h2>底图素材库</h2><p class="hint">从当前 ROM 读取实际图片；点缩略图查看或选择。</p></div><button id="closeMapAssets" aria-label="关闭素材库">✕</button></div><div class="assetcategories"><button data-assets="cells" class="${assetKind==='cells'?'primary':''}">本图现有地块（${cells.length}）</button><button data-assets="battle" class="${assetKind==='battle'?'primary':''}">全部战场底图（46）</button><button data-assets="story" class="${assetKind==='story'?'primary':''}">剧情背景（${backgrounds.length}）</button></div><p class="hint">${assetKind==='cells'?'选地块后点“用这个地块绘制”，再点地图目标格。只列出本图已有的图案与地形组合。':assetKind==='battle'?'所有战场底图都在这里。可以查看、另存 PNG，或进入对应战场编辑；不同地图的图块资源不支持直接混贴。':'这些是对话时显示的背景上半屏。可以查看、另存 PNG；这里的选择用于浏览，不会自动更换剧情背景。'}</p><div class="assetbody"><div id="assetGrid" class="assetgrid ${assetKind==='cells'?'cellgrid':''}"></div><div class="assetpreview"><p id="assetTitle">点击左侧缩略图</p><div class="assetpreviewscroll"><canvas id="assetPreview" hidden></canvas></div><p id="assetDescription" class="hint"></p><div class="toolbar"><button id="useAsset" disabled>选择素材</button><button id="saveAssetImage" disabled>另存为 PNG</button></div></div></div>`;
 $('#closeMapAssets').onclick=()=>dialog.close();dialog.querySelectorAll('[data-assets]').forEach(b=>b.onclick=()=>{assetKind=b.dataset.assets;assetSelection=null;renderMapAssets();});
 const grid=$('#assetGrid'),mapImage=assetKind==='cells'?model.renderMap(stage):null,source=document.createElement('canvas');if(mapImage)putImage(source,mapImage);const titles=new Map(model.flowItems().filter(x=>['battle','branch'].includes(x.kind)).map(x=>[x.scene,x.title]));
 const entries=assetKind==='cells'?cells:assetKind==='battle'?Array.from({length:46},(_,i)=>({id:i+1})):backgrounds.map(id=>({id}));
 for(const entry of entries){const b=document.createElement('button');b.className='assetcard';b.dataset.asset=assetKind==='cells'?`${entry.x},${entry.y}`:entry.id;const canvas=document.createElement('canvas'),label=document.createElement('span');if(assetKind==='cells'){canvas.width=64;canvas.height=32;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.drawImage(source,entry.x*32,entry.y*16,32,16,0,0,64,32);label.textContent=`${terrainLabel(entry.terrain)} (${entry.x}, ${entry.y})`;}else{const img=assetKind==='battle'?model.renderMap(entry.id):model.renderBackground(stage,entry.id),tmp=document.createElement('canvas');putImage(tmp,img);canvas.width=assetKind==='battle'?170:240;canvas.height=assetKind==='battle'?110:80;const c=canvas.getContext('2d');c.fillStyle='#203425';c.fillRect(0,0,canvas.width,canvas.height);c.imageSmoothingEnabled=false;const scale=Math.min(canvas.width/img.width,canvas.height/img.height);c.drawImage(tmp,(canvas.width-img.width*scale)/2,(canvas.height-img.height*scale)/2,img.width*scale,img.height*scale);label.textContent=assetKind==='battle'?`战场 ${entry.id} · ${titles.get(entry.id)||'原版战场'}`:`剧情背景 ${entry.id}`;}b.append(canvas,label);b.onclick=()=>{assetSelection={kind:assetKind,...entry};grid.querySelectorAll('.assetcard').forEach(x=>x.classList.toggle('selected',x===b));const preview=$('#assetPreview');preview.hidden=false;if(assetKind==='cells'){preview.width=32;preview.height=16;preview.getContext('2d').drawImage(source,entry.x*32,entry.y*16,32,16,0,0,32,16);}else putImage(preview,assetKind==='battle'?model.renderMap(entry.id):model.renderBackground(stage,entry.id));$('#assetTitle').textContent=label.textContent;$('#assetDescription').textContent=assetKind==='cells'?'将此格用作底图笔刷；是否复制通行规则由地图页的勾选项决定。':`${preview.width} × ${preview.height} 像素`;$('#useAsset').textContent=assetKind==='cells'?'用这个地块绘制':assetKind==='battle'?'编辑这张地图':'仅供背景预览';$('#useAsset').disabled=assetKind==='story';$('#saveAssetImage').disabled=false;};grid.append(b);}
 $('#useAsset').onclick=()=>{const a=assetSelection;if(!a)return;dialog.close();if(a.kind==='cells'){stamp={x:a.x,y:a.y};mapTool='stamp';mapFeedback=`已选底图样本 (${a.x}, ${a.y})，点击目标格绘制。`;}else{stage=a.id;$('#stage').value=stage;currentFlow=null;mapSelection={x:0,y:0};mapFeedback='已打开所选战场的地图。';}tab='map';render();updateStatus();};
 $('#saveAssetImage').onclick=()=>{const a=assetSelection;if(!a)return;$('#assetPreview').toBlob(blob=>{if(blob)download(blob,a.kind==='cells'?`战场${stage}_地块_${a.x}_${a.y}.png`:a.kind==='battle'?`战场${a.id}_底图.png`:`剧情背景${a.id}.png`,'image/png');},'image/png');};
}
